<?php declare(strict_types=1);
final class Resume extends Model {
 public function all(int $userId,string $table): array { $allowed=['work_experiences','educations','certifications']; if(!in_array($table,$allowed,true))return []; $s=$this->db->prepare("SELECT * FROM {$table} WHERE user_id=:uid ORDER BY created_at DESC");$s->execute(['uid'=>$userId]);return $s->fetchAll(); }
 public function create(int $uid,string $type,array $d): void { $map=['experience'=>['work_experiences',['company_name','job_title','location','start_date','end_date','is_current','description']],'education'=>['educations',['institution','degree','field_of_study','start_date','end_date','description']],'certification'=>['certifications',['name','issuing_organization','issue_date','expiry_date','credential_id','credential_url','description']]];[$table,$fields]=$map[$type];$cols=implode(',',array_merge(['user_id'],$fields));$params=array_merge(['user_id'=>$uid],array_intersect_key($d,array_flip($fields)));$marks=implode(',',array_map(fn($f)=>':'.$f,array_keys($params)));$this->db->prepare("INSERT INTO {$table} ({$cols}) VALUES ({$marks})")->execute($params);}
 public function delete(int $uid,string $type,int $id): void { $table=['experience'=>'work_experiences','education'=>'educations','certification'=>'certifications'][$type];$s=$this->db->prepare("DELETE FROM {$table} WHERE id=:id AND user_id=:uid");$s->execute(['id'=>$id,'uid'=>$uid]); }
}